            aOrbiterE = (aWandererK + RotL64(aIngress, 39U)) + 0xD96741706F3DBFBDULL;
            aOrbiterK = ((aWandererD + RotL64(aCross, 48U)) + 0x96AF30D697814E91ULL) + aOASaltC[(((511U - aIndex) + 2U)) & S_SALT1];
