            aOrbiterA = (((aWandererF + RotL64(aIngress, 11U)) + RotL64(aCarry, 11U)) + 0xF817276E03A6BCDDULL) + aOASaltF[(((511U - aIndex) + 392U)) & S_SALT1];
            aOrbiterG = ((aWandererI + RotL64(aCross, 5U)) + RotL64(aCarry, 27U)) + 0xFA4F79DCE52C9770ULL;
