            aOrbiterE = RotL64((aOrbiterE * 0x57ED20C130C0FDFDULL), 35U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterJ, 5U);
            aIngress = aIngress + (RotL64(aOrbiterK, 19U) ^ aOrbiterG);
            aIngress = aIngress + (aOrbiterH ^ RotL64(aOrbiterF, 26U));
            aIngress = aIngress + RotL64(aOrbiterE, 51U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererD = aWandererD + (((RotL64(aScatter, 60U) + RotL64(aOrbiterA, 19U)) + aOrbiterK) + aWUSaltF[(((511U - aIndex) + 491U)) & S_SALT1]);
