            aScatter = (RotL64(aPrevious, 5U) + RotL64(aCarry, 54U)) ^ (RotL64(aCross, 41U) ^ RotL64(aIngress, 23U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterB = (((aWandererG + RotL64(aIngress, 5U)) + RotL64(aCarry, 43U)) + 0xE2E9C77397883ECFULL) + aOASaltC[(((511U - aIndex) + 5U)) & S_SALT1];
            aOrbiterK = (((aWandererC + RotL64(aPrevious, 51U)) + RotL64(aCarry, 57U)) + 0xC281D7D68D2A535DULL) + aOASaltG[(((511U - aIndex) + 373U)) & S_SALT1];
            aOrbiterH = (aWandererJ + RotL64(aCross, 19U)) + 0x24A9369F37622115ULL;
            aOrbiterJ = (aWandererD + RotL64(aScatter, 57U)) + 0xF8A115F6177B4B4CULL;
            aOrbiterF = (((aWandererK + RotL64(aCross, 11U)) + RotL64(aCarry, 11U)) + 0xCB8D4887C0F962F1ULL) + aOASaltD[(((511U - aIndex) + 4U)) & S_SALT1];
            aOrbiterC = ((aWandererI + RotL64(aPrevious, 28U)) + 0x25ED37EB5444F99BULL) + aOASaltB[((aIndex + 377U)) & S_SALT1];
            aOrbiterI = (aWandererH + RotL64(aScatter, 37U)) + 0x58A503CCA9187137ULL;
            //
            aOrbiterB = ((aOrbiterB + aOrbiterK) + 0x3B12D3B40C055701ULL) + aOUSaltD[((aIndex + 387U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x5B0C27AFE4110E52ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xA66B875988DB3B83ULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x84E43BB555F6C9E1ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterJ) ^ 0xDE9E0B0C2778A02CULL) ^ aOUSaltF[(((511U - aIndex) + 93U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x563CCDE9C34CAF53ULL), 51U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x1AB7B21B962E9F99ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterH) ^ 0xA71A03EBC812FDDEULL) ^ aOUSaltA[((aIndex + 48U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x53AC0D48331B07E1ULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x564F07A7922AB8E5ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterI) ^ 0x49725EFBD1AA3871ULL) ^ aOUSaltC[(((511U - aIndex) + 270U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xAAE7103A8E53C70DULL), 43U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xC39474046712C569ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x9EAEFA0E78C05133ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xBF0D22CE548B47A9ULL), 29U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0x525EA6D22FC95543ULL) + aOUSaltB[((aIndex + 302U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x4B9A701099FAEE14ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x4D7E84425F08368BULL), 19U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x65B60DCA7BC7D2ABULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x923168BB5988A614ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xF3661242D5FC82FDULL), 3U);
