            //
            aIngress = (RotL64(aFuseLaneB[((aIndex + 18716U)) & S_BLOCK1], 21U) ^ RotL64(aWindLaneD[((aIndex + 16477U)) & S_BLOCK1], 11U));
            aIngress ^= (RotL64(aHeartLaneD[((aIndex + 24563U)) & S_BLOCK1], 46U) ^ RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 20605U)) & S_BLOCK1], 29U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
