            //
            aOrbiterI = ((aWandererB + RotL64(aIngress, 57U)) + RotL64(aCarry, 53U)) + 0x64D163215ED68F82ULL;
            aOrbiterB = (((aWandererI + RotL64(aPrevious, 19U)) + RotL64(aCarry, 27U)) + 0x41340D7C4C81B2B0ULL) + aOASaltA[(((511U - aIndex) + 260U)) & S_SALT1];
            aOrbiterD = ((aWandererF + RotL64(aCross, 13U)) + 0x85DDC0C35CAD87C3ULL) + aOASaltD[(((511U - aIndex) + 74U)) & S_SALT1];
            aOrbiterA = ((aWandererK + RotL64(aScatter, 27U)) + RotL64(aCarry, 13U)) + 0x1BDC0C992639EB6EULL;
